#!/usr/bin/env python3
# SkillSwap 5.0 Termux Update Installer

import os
import sys
import json
import base64
import zlib

PAYLOAD_B64 = ""

def main():
    print("==================================================")
    print("      SkillSwap 5.0 - Termux Update Installer     ")
    print("==================================================")
    
    target_dir = os.getcwd()
    if not os.path.exists(os.path.join(target_dir, "package.json")):
        alt_path = os.path.expanduser("~/skillswap5.0")
        if os.path.exists(os.path.join(alt_path, "package.json")):
            target_dir = alt_path
        else:
            print("[?] 'package.json' not found in current directory.")
            user_input = input("Enter path to your skillswap5.0 directory: ").strip()
            if user_input and os.path.exists(user_input):
                target_dir = os.path.abspath(user_input)
            else:
                print("[!] Invalid directory. Exiting.")
                sys.exit(1)

    print(f"[*] Updating files in: {target_dir}")

    try:
        raw_json = zlib.decompress(base64.b64decode(PAYLOAD_B64)).decode('utf-8')
        files_data = json.loads(raw_json)
    except Exception as e:
        print(f"[!] Error decoding payload: {e}")
        sys.exit(1)

    for relative_path, content in files_data.items():
        full_path = os.path.join(target_dir, relative_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        with open(full_path, "w", encoding="utf-8", errors="ignore") as f_out:
            f_out.write(content)
        print(f"  [✓] Updated: {relative_path}")

    print("\n==================================================")
    print(" [SUCCESS] All SkillSwap 5.0 features updated!")
    print(" Updated files:")
    for relative_path in files_data.keys():
        print(f"   - {relative_path}")
    print("==================================================\n")

if __name__ == "__main__":
    main()
